389	
390		// 省略 labels：该指标全部序列（共 4 条），不合并；顺序沿用 snapshot 排序。
391		res := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":2}`)
392		if len(res.Series) != 4 {
393			t.Fatalf("all series = %+v, want 4", res.Series)
394		}
395		wantOrder := []map[string]string{
396			{},
397			{"host": "h", "zone": "x"},
398			{"zone": ""},
399			{"zone": "x"},
400		}
401		for i, wantLabels := range wantOrder {
402			got := res.Series[i].Labels
403			if len(got) != len(wantLabels) {
404				t.Fatalf("series[%d] labels = %v, want %v", i, got, wantLabels)
405			}
406			for k, v := range wantLabels {
