428		if len(res.Series) != 1 || res.Series[0].Average != 4 {
429			t.Fatalf("fully specified match = %+v, want average 4", res.Series)
430		}
431	
432		// 空字符串只匹配真实存在的空值标签，不匹配缺少该标签的序列。
433		res = mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":2,"labels":{"zone":""}}`)
434		if len(res.Series) != 1 || res.Series[0].Average != 2 {
435			t.Fatalf("empty-value match = %+v, want single series avg 2", res.Series)
436		}
437	
438		// 要求一个不存在的标签：空结果。
439		res = mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":2,"labels":{"nope":"x"}}`)
440		if len(res.Series) != 0 {
441			t.Fatalf("missing label match = %+v, want empty", res.Series)
442		}
443	
444		// 标签顺序不影响匹配。
