571			t.Fatalf("average = %v, want %v", s0.Average, 1.0/3.0)
572		}
573		b, _ := json.Marshal(s0.Average)
574		if string(b) != "0.3333333333333333" {
575			t.Fatalf("average JSON = %s, want 0.3333333333333333", b)
576		}
577	}
578	
579	func TestQueryAverageOrderAndBatchIndependent(t *testing.T) {
580		// 同一组数值：不同批次划分、不同提交顺序、区间内时间戳顺序不同，均值必须一致。
581		setups := [][]string{
582			{`[{"name":"m","timestamp":1,"value":1e16},{"name":"m","timestamp":2,"value":1},{"name":"m","timestamp":3,"value":-1e16}]`},
583			{`[{"name":"m","timestamp":3,"value":-1e16}]`, `[{"name":"m","timestamp":1,"value":1e16},{"name":"m","timestamp":2,"value":1}]`},
584			{`[{"name":"m","timestamp":2,"value":1}]`, `[{"name":"m","timestamp":3,"value":-1e16}]`, `[{"name":"m","timestamp":1,"value":1e16}]`},
585			{`[{"name":"m","timestamp":1,"value":-1e16},{"name":"m","timestamp":2,"value":1},{"name":"m","timestamp":3,"value":1e16}]`},
586		}
587		want := 1.0 / 3.0
588		for i, batches := range setups {
589			store := NewMetricStore()
590			for _, line := range batches {
591				mustOK(t, store, line)
592			}
593			res := mustQuery(t, store, `{"op":"query","name":"m","start":1,"end":3}`)
594			if len(res.Series) != 1 || res.Series[0].Count != 3 || res.Series[0].Average != want {
595				t.Fatalf("setup %d: got %+v, want count=3 average=%v", i, res.Series, want)
596			}
597		}
598	}
599	
600	func TestQueryAverageSumOverflowStaysFinite(t *testing.T) {
601		store := NewMetricStore()
602		// 总和 3e308 超出 float64 范围，但平均值必须有限且精确。
603		mustOK(t, store, `[
604			{"name":"m","timestamp":1,"value":1e308},
605			{"name":"m","timestamp":2,"value":1e308},
606			{"name":"m","timestamp":3,"value":1e308}
607		]`)
608		res := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":10}`)
609		avg := res.Series[0].Average
610		if math.IsInf(avg, 0) || math.IsNaN(avg) || avg != 1e308 {
611			t.Fatalf("average = %v, want 1e308", avg)
612		}
613	
614		// 最大有限值自身重复：平均仍为 MaxFloat64，不溢出为 +Inf。
615		store2 := NewMetricStore()
616		mustOK(t, store2, `[
617			{"name":"m","timestamp":1,"value":1.7976931348623157e308},
618			{"name":"m","timestamp":2,"value":1.7976931348623157e308}
619		]`)
620		res = mustQuery(t, store2, `{"op":"query","name":"m","start":0,"end":10}`)
621		if avg = res.Series[0].Average; avg != math.MaxFloat64 {
622			t.Fatalf("average = %v, want MaxFloat64", avg)
623		}
624	}
625	
626	func TestQueryAverageExactZeroIsPositiveZero(t *testing.T) {
627		store := NewMetricStore()
628		mustOK(t, store, `[
629			{"name":"m","timestamp":1,"value":1e308},
630			{"name":"m","timestamp":2,"value":-1e308},
631			{"name":"m","timestamp":3,"value":5},
632			{"name":"m","timestamp":4,"value":-5}
633		]`)
634		res := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":10}`)
635		avg := res.Series[0].Average
636		if avg != 0 || math.Signbit(avg) {
637			t.Fatalf("exact zero average = %v (signbit=%v), want +0", avg, math.Signbit(avg))
638		}
639		b, _ := json.Marshal(avg)
640		if string(b) != "0" {
641			t.Fatalf("zero average JSON = %s, want 0", b)
642		}
643	}
644	
645	func TestQueryAverageSubnormalAndRounding(t *testing.T) {
646		// 最小次正规值参与平均不得被提前冲刷为零。
647		store := NewMetricStore()
648		mustOK(t, store, `[
649			{"name":"m","timestamp":1,"value":5e-324},
650			{"name":"m","timestamp":2,"value":5e-324}
651		]`)
652		res := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":10}`)
653		if avg := res.Series[0].Average; avg != 5e-324 {
654			t.Fatalf("average = %v, want 5e-324", avg)
655		}
656	
657		// 精确平均恰为 2^-1075（0 与最小次正规值正中）：按最近偶数舍入为 0。
658		store2 := NewMetricStore()
659		mustOK(t, store2, `[
660			{"name":"m","timestamp":1,"value":5e-324},
661			{"name":"m","timestamp":2,"value":0}
662		]`)
663		res = mustQuery(t, store2, `{"op":"query","name":"m","start":0,"end":10}`)
664		if avg := res.Series[0].Average; avg != 0 {
665			t.Fatalf("tie at 2^-1075 must round to even (0), got %v", avg)
666		}
667	
668		// 单点序列返回该点的值本身。
669		store3 := NewMetricStore()
670		mustOK(t, store3, `[{"name":"m","timestamp":7,"value":0.1}]`)
671		res = mustQuery(t, store3, `{"op":"query","name":"m","start":0,"end":10}`)
672		if avg := res.Series[0].Average; avg != 0.1 {
673			t.Fatalf("single point average = %v, want 0.1", avg)
674		}
675	}
676	
677	func TestQueryValidationErrors(t *testing.T) {
678		store := NewMetricStore()
679		mustOK(t, store, `[{"name":"m","timestamp":1,"value":1}]`)
680		bad := []string{
681			`{"op":"query","name":"","start":0,"end":1}`,                                        // 空 name
682			`{"op":"query","name":7,"start":0,"end":1}`,                                         // name 类型错误
683			`{"op":"query","name":"m","start":0}`,                                               // 缺 end
684			`{"op":"query","name":"m","start":0,"end":1,"extra":1}`,                             // 未知字段
685			`{"op":"ingest","name":"m","start":0,"end":1}`,                                      // 未知 op
686			`{"op":"write","name":"m","start":0,"end":1}`,                                       // 其他 op
687			`{"op":7,"name":"m","start":0,"end":1}`,                                             // op 类型错误
688			`{"op":"query","op":"query","name":"m","start":0,"end":1}`,                          // 重复字段
689			`{"op":"query","name":"m","start":0.5,"end":1}`,                                     // start 非整数
690			`{"op":"query","name":"m","start":"0","end":1}`,                                     // start 字符串
691			`{"op":"query","name":"m","start":true,"end":1}`,                                    // start 布尔
692			`{"op":"query","name":"m","start":0,"end":9223372036854775808}`,                     // end 超 int64
693			`{"op":"query","name":"m","start":2,"end":1}`,                                       // start > end
694			`{"op":"query","name":"m","start":-9223372036854775808,"end":-9223372036854775809}`, // end 低于 int64
695			`{"op":"query","name":"m","start":0,"end":1,"labels":[]}`,                           // labels 非对象
696			`{"op":"query","name":"m","start":0,"end":1,"labels":null}`,                         // labels 为 null
697			`{"op":"query","name":"m","start":0,"end":1,"labels":{"":"v"}}`,                     // 空标签键
698			`{"op":"query","name":"m","start":0,"end":1,"labels":{"k":1}}`,                      // 标签值非字符串
699			`{"op":"query","name":"m","start":0,"end":1,"labels":{"k":"a","k":"b"}}`,            // 重复标签键
700			`{"name":"m","start":0,"end":1}`,                                                    // 缺 op
701			`{"op":"query","start":0,"end":1}`,                                                  // 缺 name
702			`{"op":"query","name":"m","start":0,"end":1} trailing`,                              // 尾随内容
703		}
704		for _, line := range bad {
705			lerr := mustQueryFail(t, store, line)
706			if lerr.Index != 0 {
707				t.Errorf("line %s: query errors must not carry index, got %d", line, lerr.Index)
708			}
709			if lerr.Conflict != nil {
710				t.Errorf("line %s: query errors must not carry conflict", line)
711			}
712		}
713		// 非法行不改变存储。
714		res := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":100}`)
715		if len(res.Series) != 1 || res.Series[0].Count != 1 {
716			t.Fatalf("failed queries must not mutate storage, got %+v", res.Series)
717		}
718	}
719	
720	func TestProcessLineDispatchesArrayAndObject(t *testing.T) {
721		store := NewMetricStore()
722		r, lerr := store.ProcessLine(`[{"name":"m","timestamp":1,"value":2}]`)
723		if lerr != nil {
724			t.Fatalf("array line: %+v", lerr)
725		}
726		if _, ok := r.(*BatchResult); !ok {
727			t.Fatalf("array line result type = %T, want *BatchResult", r)
728		}
729		r, lerr = store.ProcessLine(`{"op":"query","name":"m","start":0,"end":10}`)
730		if lerr != nil {
731			t.Fatalf("object line: %+v", lerr)
732		}
733		qr, ok := r.(*QueryResult)
734		if !ok {
735			t.Fatalf("object line result type = %T, want *QueryResult", r)
736		}
737		if len(qr.Series) != 1 || qr.Series[0].Average != 2 {
738			t.Fatalf("query via ProcessLine = %+v", qr)
739		}
740		// 标量顶层值仍然是整行错误，且不带 index。
741		_, lerr = store.ProcessLine(`"hello"`)
742		if lerr == nil || lerr.Index != 0 {
743			t.Fatalf("scalar line = %+v, want whole-line error without index", lerr)
744		}
745		_, lerr = store.ProcessLine(`{}`)
746		if lerr == nil {
747			t.Fatal("empty object must fail validation")
748		}
749	}
