14	// findViewIndex 在写入快照中找到指定指标名与完整标签集合的序列下标。
15	func findViewIndex(t *testing.T, res *BatchResult, name string, labels map[string]string) int {
16		t.Helper()
17		for i, v := range res.Series {
18			if v.Name == name && reflect.DeepEqual(v.Labels, labels) {
19				return i
20			}
21		}
22		t.Fatalf("series %s %v not found in snapshot: %+v", name, labels, res.Series)
23		return -1
24	}
