241	// 查询结果是独立结果：改返回条目的标签、count、average 或整理结果条目，
242	// 不污染另一份已取得的查询结果，也不影响存储与之后的写入快照。
243	func TestQueryResultMutationDoesNotChangeStorage(t *testing.T) {
244		s := NewMetricStore()
245		mustOK(t, s, `[
246			{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}},
247			{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},
248			{"name":"cpu","timestamp":1000,"value":5,"labels":{"host":"b"}},
249			{"name":"cpu","timestamp":1000,"value":6},
250			{"name":"cpu","timestamp":1000,"value":7,"labels":{"zone":""}}
251		]`)
252	
253		// 先保留一份成功结果，随后修改另一份。
254		q0 := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000}`)
255		assertFullCPUResult(t, q0)
256		q1 := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000}`)
257	
258		// 调用方整理 q1 的各条目：改名、改标签、删标签、加标签，篡改 count/average。
259		a := &q1.Series[findQueryIndex(t, q1, "cpu", map[string]string{"host": "a"})]
260		a.Name = "cpu-renamed"
261		a.Labels["host"] = "c"
262		a.Labels["extra"] = "e"
263		a.Count = 99
264		a.Average = 123
265	
266		b := &q1.Series[findQueryIndex(t, q1, "cpu", map[string]string{"host": "b"})]
267		delete(b.Labels, "host")
268		b.Labels["host"] = "d"
269		b.Count = 7
270		b.Average = 77
271	
272		none := &q1.Series[findQueryIndex(t, q1, "cpu", map[string]string{})]
273		if none.Labels == nil {
274			t.Fatal("query labels for unlabeled series must be non-nil empty map")
275		}
276		none.Labels["host"] = "x"
277		none.Count = 41
278		none.Average = 42
279	
280		emptyVal := &q1.Series[findQueryIndex(t, q1, "cpu", map[string]string{"zone": ""})]
281		delete(emptyVal.Labels, "zone")
282		emptyVal.Count = 5
283		emptyVal.Average = 9
284	
285		// 整理结果中的序列条目：反转顺序、截断并追加伪造条目、篡改信封字段。
286		for i, j := 0, len(q1.Series)-1; i < j; i, j = i+1, j-1 {
287			q1.Series[i], q1.Series[j] = q1.Series[j], q1.Series[i]
288		}
289		q1.Series = append(q1.Series[:1], QuerySeries{Name: "ghost", Labels: map[string]string{}, Count: 1})
290		q1.Status = "mutated"
291		q1.Op = "mutated"
292	
293		// 另一份此前取得的查询结果不被污染。
294		assertFullCPUResult(t, q0)
295		// 之后取得的查询结果仍按存储事实返回。
296		q2 := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000}`)
297		assertFullCPUResult(t, q2)
298	
299		// 之后的写入快照同样不被污染。
300		snap := mustOK(t, s, `[]`)
301		if len(snap.Series) != 4 {
302			t.Fatalf("snapshot after query mutation = %+v, want 4 series", snap.Series)
303		}
304		for _, want := range []struct {
305			labels map[string]string
306			value  float64
307		}{
308			{map[string]string{}, 6},
309			{map[string]string{"host": "a"}, 2},
310			{map[string]string{"host": "b"}, 5},
311			{map[string]string{"zone": ""}, 7},
312		} {
313			v := snap.Series[findViewIndex(t, snap, "cpu", want.labels)]
314			if v.Points[0].Value != want.value {
315				t.Fatalf("snapshot point for %v = %+v, want value %v", want.labels, v.Points, want.value)
316			}
317		}
318	
319		// 按改出的身份筛选查不到序列；原标签规则保持不变。
320		for _, line := range []string{
321			`{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"c"}}`,
322			`{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"d"}}`,
323			`{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"x"}}`,
324			`{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"a","extra":"e"}}`,
325			`{"op":"query","name":"cpu-renamed","start":0,"end":10000}`,
326			`{"op":"query","name":"ghost","start":0,"end":10000}`,
327		} {
328			if qr := mustQuery(t, s, line); len(qr.Series) != 0 {
329				t.Fatalf("mutated identity %s must not match, got %+v", line, qr.Series)
330			}
331		}
332		// 删除返回条目的空值标签不改变存储身份：空值筛选仍命中该序列。
333		qr := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"zone":""}}`)
334		if len(qr.Series) != 1 || qr.Series[0].Count != 1 || qr.Series[0].Average != 7 {
335			t.Fatalf("empty-value label selection = %+v, want the zone='' series", qr.Series)
336		}
337	}
